contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint dep, uint am, uint m) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep > 0);
        require(am > 0 && am <= dep);
        require(m > 0 && m <= dep);
        require(address(this).balance >= dep);
        c.SetMinSum(m); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        c.Initialized(); if (__ESBMC_reverted()) return;
        uint b0 = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint cb0 = address(c).balance;
        uint my0 = address(this).balance;
        c.Collect(am); if (__ESBMC_reverted()) return;
        assert(c.balances(address(this)) == b0 - am &&
               address(c).balance == cb0 - am &&
               address(this).balance == my0 + am);
    }
    receive() external payable {}
}

