pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 dep, uint256 am, uint256 m) internal {
        dep = bound(dep, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(dep > 0);
        vm.assume(am > 0 && am <= dep);
        vm.assume(m > 0 && m <= dep);
        vm.assume(address(this).balance >= dep);
        try c.SetMinSum(m) {} catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.Deposit{value: dep}() {} catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 b0;
        try c.balances(address(this)) returns (uint256 __r) { b0 = __r; } catch { return; }
        uint cb0 = address(c).balance;
        uint my0 = address(this).balance;
        try c.Collect(am) {} catch { return; }
        assertTrue(c.balances(address(this)) == b0 - am &&
               address(c).balance == cb0 - am &&
               address(this).balance == my0 + am);
    }

    function testFuzz_run(uint256 dep, uint256 am, uint256 m) public {
        _run(dep, am, m);
    }

    receive() external payable {}
}
